#!/usr/bin/env Rscript
suppressPackageStartupMessages({library(data.table);library(clusterProfiler);library(org.Hs.eg.db);library(AnnotationDbi);library(msigdbr)})
args<-commandArgs(trailingOnly=TRUE);if(length(args)!=2L)stop('Usage: 07_characterize_phase77_signatures_v1.R <training_dir> <outdir>')
training<-normalizePath(args[[1]],winslash='/',mustWork=TRUE);out<-normalizePath(args[[2]],winslash='/',mustWork=FALSE);part<-paste0(out,'.part');if(dir.exists(out)||file.exists(out)||dir.exists(part)||file.exists(part))stop('refusing existing output');dir.create(part,recursive=TRUE)
atomic_fwrite<-function(x,p){tmp<-paste0(p,'.part');fwrite(x,tmp,sep='\t',quote=TRUE,na='NA');if(!file.rename(tmp,p))stop('rename failed')}
sig<-fread(file.path(training,'phase77_weighted_signatures_v1.tsv'));de<-fread(file.path(training,'GSE249082_direct_MTA_edgeR_v1.tsv'));universe<-unique(de$human_symbol)
msig_h<-as.data.table(msigdbr(db_species='HS',species='Homo sapiens',collection='H'))
msig_k<-as.data.table(msigdbr(db_species='HS',species='Homo sapiens',collection='C2'));msig_k<-msig_k[gs_subcollection%chin%c('CP:KEGG_LEGACY','CP:KEGG_MEDICUS')]
sets<-unique(sig[,.(signature_id,direction)]);all_enrich<-list();idx<-0L
standard<-function(e,sig_id,dir,ont){if(is.null(e)||nrow(as.data.frame(e))==0L)return(NULL);z<-as.data.table(as.data.frame(e));data.table(signature_id=sig_id,direction=dir,ontology=ont,term_id=z$ID,description=z$Description,gene_ratio=z$GeneRatio,bg_ratio=z$BgRatio,p_value=z$pvalue,q_value=z$p.adjust,gene_count=z$Count,genes=z$geneID)}
for(i in seq_len(nrow(sets))){sid<-sets$signature_id[i];dr<-sets$direction[i];genes<-sig[signature_id==sid&direction==dr,human_symbol];if(length(genes)<5L)next;entrez<-na.omit(unique(unname(mapIds(org.Hs.eg.db,keys=genes,keytype='SYMBOL',column='ENTREZID',multiVals='first'))));uentrez<-na.omit(unique(unname(mapIds(org.Hs.eg.db,keys=universe,keytype='SYMBOL',column='ENTREZID',multiVals='first'))));e<-suppressMessages(enrichGO(gene=entrez,universe=uentrez,OrgDb=org.Hs.eg.db,keyType='ENTREZID',ont='BP',pAdjustMethod='BH',pvalueCutoff=1,qvalueCutoff=1,minGSSize=5,maxGSSize=500,readable=TRUE));idx<-idx+1L;all_enrich[[idx]]<-standard(e,sid,dr,'GO_BP');for(ont in c('HALLMARK','KEGG')){d<-if(ont=='HALLMARK')msig_h else msig_k;term2gene<-unique(d[,.(term=gs_name,gene=toupper(gene_symbol))]);term2name<-unique(d[,.(term=gs_name,name=gs_name)]);ee<-suppressMessages(enricher(gene=genes,universe=universe,TERM2GENE=term2gene,TERM2NAME=term2name,pAdjustMethod='BH',pvalueCutoff=1,qvalueCutoff=1,minGSSize=5,maxGSSize=500));idx<-idx+1L;all_enrich[[idx]]<-standard(ee,sid,dr,ont)}}
enrich<-rbindlist(all_enrich,fill=TRUE);if(nrow(enrich))setorder(enrich,signature_id,direction,ontology,q_value,p_value)
MARKERS<-list(MACROPHAGE_MTA_ANCHORS=c('ARG1','VEGFA','IL10','TIMP1'),SPP1_STATE_NO_SPP1=c('GPNMB','LGALS3','FABP5','CD9','LPL'),IMMUNOSUPPRESSION_NO_IL10=c('TGFB1','VSIG4','MARCO','CD274','IDO1'),MONOCYTE_PROGRAM=c('FCN1','VCAN','S100A8','S100A9','CTSS','LILRB1'),FIBROBLAST_ECM=c('POSTN','COL1A1','COL1A2','COL3A1','COL4A1','COL4A2','COL5A1','COL5A2','FN1','FAP','PDGFRA','LOX','LOXL2','MMP2','MMP14','THBS1','TGFBI'),VASCULAR_NO_VEGFA=c('MMP9','MMP14','ANGPTL4','IL1B','LGALS3'))
overlap<-rbindlist(lapply(unique(sig$signature_id),function(sid)rbindlist(lapply(names(MARKERS),function(m){g<-sig[signature_id==sid,human_symbol];hit<-intersect(g,MARKERS[[m]]);data.table(signature_id=sid,marker_set=m,signature_genes=length(g),marker_genes=length(MARKERS[[m]]),overlap_count=length(hit),overlap_genes=paste(hit,collapse=';'))}))))
atomic_fwrite(enrich,file.path(part,'phase77_signature_enrichment_all_v1.tsv'));atomic_fwrite(enrich[q_value<0.05],file.path(part,'phase77_signature_enrichment_fdr_v1.tsv'));atomic_fwrite(overlap,file.path(part,'phase77_signature_marker_overlap_v1.tsv'))
summary<-data.table(status='PASS_PHASE77_CHARACTERIZATION',enrichment_rows=nrow(enrich),fdr_rows=sum(enrich$q_value<0.05),marker_overlap_rows=nrow(overlap));atomic_fwrite(summary,file.path(part,'run_metadata_v1.tsv'));if(!file.rename(part,out))stop('rename failed');cat(sprintf('{"status":"PASS_PHASE77_CHARACTERIZATION","enrichment_rows":%d,"fdr_rows":%d}\n',nrow(enrich),sum(enrich$q_value<0.05)))
